"""The network emulation engine.

:class:`Mininet` instantiates a :class:`~netsim.topo.Topo` into live node and
link objects and provides the measurement primitives the experiments use:
``ping``/``pingAll`` (reachability + loss), ``iperf`` (throughput) and
``avg_rtt`` (latency).
"""

from .graph import WeightedGraph
from .link import DEFAULT_BW_MBPS, TCLink
from .node import Controller, Host, OVSSwitch, Switch
from .topo import natural_key
from .utils import (compute_bottleneck_bw, compute_path_delay,
                    compute_path_loss_rate, generate_ip)


class Mininet:
    """Simulated network built from a topology."""

    def __init__(self, topo=None, switch=OVSSwitch, host=Host, link=TCLink,
                 controller=Controller, ipBase="10.0.0.0/8", build=True,
                 autoSetMacs=False, **params):
        self.topo = topo
        self.switch = switch
        self.host = host
        self.link = link
        self.controller = controller
        self.ipBase = ipBase
        self.autoSetMacs = autoSetMacs
        self.params = dict(params)

        self.hosts = []
        self.switches = []
        self.controllers = []
        self.links = []
        self.nameToNode = {}
        self.graph = WeightedGraph()

        self.built = False
        self.started = False
        self.next_ip_index = 0

        if topo is not None and build:
            self.build()

    # -- node/link creation -------------------------------------------------
    def addHost(self, name, cls=None, **params):
        cls = cls or self.host
        node = cls(name, **params)
        self.hosts.append(node)
        self.nameToNode[name] = node
        self.graph.add_node(name)
        return node

    def addSwitch(self, name, cls=None, **params):
        cls = cls or self.switch
        node = cls(name, **params)
        self.switches.append(node)
        self.nameToNode[name] = node
        self.graph.add_node(name)
        for ctrl in self.controllers:
            ctrl.register(node)
        return node

    def addController(self, name="c0", cls=None, **params):
        cls = cls or self.controller
        node = cls(name, **params) if not isinstance(name, Controller) else name
        self.controllers.append(node)
        self.nameToNode[node.name] = node
        for switch in self.switches:
            node.register(switch)
        return node

    def addLink(self, node1, node2, port1=None, port2=None, cls=None,
                **params):
        node1 = self.get(node1)
        node2 = self.get(node2)
        cls = cls or self.link
        params.pop("isSwitch", None)
        link = cls(node1, node2, port1=port1, port2=port2, **params)
        self.links.append(link)
        self.graph.add_edge(node1.name, node2.name,
                            bw=link.bandwidth(),
                            delay=link.delay,
                            loss=link.loss_rate,
                            link=link)
        return link

    # -- lifecycle ----------------------------------------------------------
    def build(self):
        """Instantiate the topology: controller, switches, hosts, then links."""
        if self.topo is not None:
            if not self.controllers and self.controller is not None:
                self.addController("c0")
            for name in self.topo.switches():
                opts = self.topo.nodeInfo(name)
                opts.pop("isSwitch", None)
                cls = opts.pop("cls", None)
                self.addSwitch(name, cls=cls, **opts)
            for name in self.topo.hosts():
                opts = self.topo.nodeInfo(name)
                opts.pop("isSwitch", None)
                cls = opts.pop("cls", None)
                self.addHost(name, cls=cls, **opts)
            for node1, node2, opts in self.topo.links(withInfo=True):
                opts = dict(opts)
                cls = opts.pop("cls", None)
                port1 = opts.pop("port1", None)
                port2 = opts.pop("port2", None)
                self.addLink(node1, node2, port1=port1, port2=port2, cls=cls,
                             **opts)
        self.built = True
        return self

    def start(self):
        """Assign IP addresses to hosts and 'boot' every node."""
        for host in self.hosts:
            if host.ip is None:
                host.setIP(generate_ip(self.next_ip_index))
            self.next_ip_index += 1
        for node in self.switches + self.controllers + self.hosts:
            node.start()
        self.started = True
        return self

    def stop(self):
        for node in self.hosts + self.switches + self.controllers:
            node.stop()
        self.started = False
        return self

    # -- lookups ------------------------------------------------------------
    def get(self, name):
        if isinstance(name, (Host, Switch, Controller)):
            return name
        if hasattr(name, "name") and name.name in self.nameToNode:
            return self.nameToNode[name.name]
        if name not in self.nameToNode:
            raise KeyError("no such node: %s" % name)
        return self.nameToNode[name]

    def __getitem__(self, name):
        return self.get(name)

    def __contains__(self, name):
        return name in self.nameToNode

    def __len__(self):
        return len(self.hosts) + len(self.switches)

    def keys(self):
        return sorted(self.nameToNode.keys(), key=natural_key)

    def total_nodes(self):
        """Hosts + switches (controllers are not part of the data plane)."""
        return len(self.hosts) + len(self.switches)

    def is_switch(self, name):
        return isinstance(self.nameToNode.get(name), Switch)

    def linksBetween(self, node1, node2):
        name1 = getattr(node1, "name", node1)
        name2 = getattr(node2, "name", node2)
        return [l for l in self.links if l.connects(name1, name2)]

    def linkBetween(self, node1, node2):
        found = self.linksBetween(node1, node2)
        return found[0] if found else None

    # -- path helpers -------------------------------------------------------
    def path(self, src, dst):
        """Shortest node-name path between two nodes (None if unreachable)."""
        return self.graph.shortest_path(getattr(src, "name", src),
                                        getattr(dst, "name", dst))

    def path_links(self, path):
        """Links traversed by a node-name path."""
        links = []
        if not path:
            return links
        for u, v in zip(path, path[1:]):
            edge = self.graph.get_edge(u, v)
            link = edge.get("link") if edge else None
            if link is None:
                link = self.linkBetween(u, v)
            if link is not None:
                links.append(link)
        return links

    def path_switches(self, path):
        """Switch nodes on a path."""
        return [self.nameToNode[n] for n in (path or [])
                if isinstance(self.nameToNode.get(n), Switch)]

    def _host_list(self, hosts=None):
        if hosts is None:
            return list(self.hosts)
        return [self.get(h) for h in hosts]

    # -- measurements -------------------------------------------------------
    def ping(self, hosts=None, timeout=None):
        """Return average packet loss (%) over all ordered host pairs.

        Unreachable pairs count as 100% loss; reachable pairs contribute the
        end-to-end loss probability implied by the per-link loss rates.
        """
        nodes = self._host_list(hosts)
        pairs = 0
        loss_total = 0.0
        for src in nodes:
            for dst in nodes:
                if src is dst:
                    continue
                pairs += 1
                path = self.path(src, dst)
                if not path or len(path) < 2:
                    loss_total += 100.0
                    continue
                rates = [l.loss_rate for l in self.path_links(path)]
                loss_total += 100.0 * compute_path_loss_rate(rates)
        if pairs == 0:
            return 0.0
        return loss_total / pairs

    def pingAll(self, timeout=None):
        """Ping between every pair of hosts, returning loss (%)."""
        return self.ping(hosts=None, timeout=timeout)

    def pingPair(self, src=None, dst=None):
        nodes = self._host_list()
        if src is None or dst is None:
            if len(nodes) < 2:
                return 0.0
            src, dst = nodes[0], nodes[1]
        return self.ping([src, dst])

    def iperf(self, hosts=None, l4Type="TCP", seconds=10, **kwargs):
        """Return achievable throughput (Mbps) between two hosts.

        Bottleneck link bandwidth, reduced by each switch's forwarding
        overhead (2% per hop by default).
        """
        nodes = self._host_list(hosts)
        if len(nodes) < 2:
            return 0.0
        src, dst = nodes[0], nodes[-1]
        path = self.path(src, dst)
        if not path or len(path) < 2:
            return 0.0
        links = self.path_links(path)
        bandwidths = [l.bandwidth(DEFAULT_BW_MBPS) for l in links]
        bw = compute_bottleneck_bw(bandwidths)
        for switch in self.path_switches(path):
            bw *= switch.throughput_factor
        return bw

    def rtt(self, src, dst):
        """Round-trip time (ms) between two nodes, or None if unreachable."""
        path = self.path(src, dst)
        if not path or len(path) < 2:
            return None
        one_way = compute_path_delay([l.delay for l in self.path_links(path)])
        return 2.0 * one_way

    def avg_rtt(self, hosts=None):
        """Average round-trip time (ms) across all reachable host pairs."""
        nodes = self._host_list(hosts)
        total = 0.0
        pairs = 0
        for i, src in enumerate(nodes):
            for dst in nodes[i + 1:]:
                value = self.rtt(src, dst)
                if value is None:
                    continue
                total += value
                pairs += 1
        if pairs == 0:
            return 0.0
        return total / pairs

    def __repr__(self):
        return "<%s hosts=%d switches=%d links=%d>" % (
            type(self).__name__, len(self.hosts), len(self.switches),
            len(self.links))

