"""SDN control-plane experiments.

A controller learns the topology of an emulated network, computes shortest
paths and programs the switches.  The experiments measure how much state that
takes (rules installed), how long the control plane needs to converge, how many
rules a link failure forces it to reinstall, how many packet-ins per second the
reactive controller services and how many rules age out once their idle timeout
elapses.
"""

from . import print_result
from ..net import Mininet
from ..sdn_controller import ProactiveController, ReactiveController
from ..targets.configs import SDN_EXPERIMENTS
from ..topo import LinearTopo, RingTopo, TreeTopo


def build_topo(cfg):
    """Build the topology described by an ``SDN_EXPERIMENTS`` entry."""
    lopts = {"bw": cfg.get("link_bw"), "delay": cfg.get("link_delay")}
    kind = cfg.get("type", "tree")
    if kind == "tree":
        return TreeTopo(depth=cfg["depth"], fanout=cfg["fanout"], lopts=lopts)
    if kind == "ring":
        return RingTopo(k=cfg["k"], lopts=lopts)
    return LinearTopo(k=cfg["k"], n=cfg.get("n", 1), lopts=lopts)


def build_control_plane(cfg, controller_cls=ProactiveController):
    """Start a network and let a controller discover it.

    Returns ``(net, controller)`` with the controller's topology graph and
    (empty) flow tables in place.
    """
    net = Mininet(topo=build_topo(cfg))
    net.start()
    controller = controller_cls("c0")
    controller.topology_discovery(net)
    return net, controller


def ingress_switch(controller, host):
    """The switch a host is attached to (its first switch neighbour)."""
    for neighbor in sorted(controller.adjacency.get(host, {})):
        if neighbor in controller.flow_tables:
            return neighbor
    return None


def proactive_control_plane():
    """A proactive controller with every host-pair path already programmed."""
    cfg = SDN_EXPERIMENTS["proactive"]
    net, controller = build_control_plane(cfg, ProactiveController)
    controller.rule_install_time_ms = cfg["rule_install_time_ms"]
    controller.install_all_rules(controller.host_ips,
                                 priority=cfg["priority"])
    return net, controller


def experiment_flow_rules_installed():
    """Flow rules held by all switches after the proactive install."""
    _, controller = proactive_control_plane()
    return controller.total_rules_installed()


def experiment_path_convergence_time():
    """Simulated time (ms) the controller needs to push all those rules."""
    _, controller = proactive_control_plane()
    return controller.total_install_time()


def experiment_link_failure_recovery():
    """Rules reinstalled on the detour paths after one link goes down."""
    cfg = SDN_EXPERIMENTS["failure"]
    _, controller = build_control_plane(cfg, ProactiveController)
    controller.install_all_rules(controller.host_ips)
    node1, node2 = cfg["failed_link"]
    return controller.handle_link_failure(node1, node2)


def experiment_controller_throughput():
    """Packet-in events the reactive controller services per second."""
    cfg = SDN_EXPERIMENTS["reactive"]
    _, controller = build_control_plane(cfg, ReactiveController)
    controller.PACKET_IN_LATENCY_MS = cfg["packet_in_latency_ms"]
    hosts = sorted(controller.host_ips)
    pairs = [(src, dst) for src in hosts for dst in hosts if src != dst]
    for index in range(int(cfg["num_packets"])):
        src, dst = pairs[index % len(pairs)]
        controller.handle_packet_in(ingress_switch(controller, src),
                                    {"src_ip": controller.ip_of(src),
                                     "dst_ip": controller.ip_of(dst)})
    return controller.packet_in_throughput()


def experiment_rule_timeout_evictions():
    """Rules evicted once their idle timeout elapses without traffic."""
    cfg = SDN_EXPERIMENTS["timeout"]
    _, controller = build_control_plane(cfg, ProactiveController)
    controller.install_all_rules(controller.host_ips,
                                 idle_timeout=cfg["idle_timeout"],
                                 install_time=cfg["install_time"])

    # Only the active flows keep matching, so only their rules stay fresh.
    last_matched = {}
    for src, dst in cfg["active_flows"]:
        headers = {"src_ip": controller.ip_of(src),
                   "dst_ip": controller.ip_of(dst)}
        for node in controller.paths.get((src, dst), []):
            table = controller.flow_tables.get(node)
            if table is None:
                continue
            rule = table.lookup(headers)
            if rule is not None:
                last_matched[rule] = cfg["refresh_time"]

    return controller.evict_expired(cfg["current_time"], last_matched)


def run_sdn_experiments():
    print_result("SDN_FLOW_RULES_INSTALLED", experiment_flow_rules_installed())
    print_result("SDN_PATH_CONVERGENCE_TIME", experiment_path_convergence_time())
    print_result("SDN_LINK_FAILURE_RECOVERY", experiment_link_failure_recovery())
    print_result("SDN_CONTROLLER_THROUGHPUT", experiment_controller_throughput())
    print_result("SDN_RULE_TIMEOUT_EVICTIONS", experiment_rule_timeout_evictions())


if __name__ == "__main__":
    run_sdn_experiments()

