def compute_all_paths(self):
    """Shortest path for every ordered pair of hosts.

    Falls back to every pair of nodes when no host has been registered
    (a controller that only learned switches still has a topology).
    """
    endpoints = self.hosts or self.nodes
    self.paths = {}
    for src in endpoints:
        for dst in endpoints:
            if src == dst:
                continue
            path = self.compute_path(src, dst)
            if path:
                self.paths[(src, dst)] = path
    return self.paths

@staticmethod
def path_uses_link(path, node1, node2):
    """True when ``path`` traverses the link between the two nodes."""
    for u, v in zip(path, path[1:]):
        if (u, v) == (node1, node2) or (u, v) == (node2, node1):
            return True
    return False

# -- rule installation --------------------------------------------------
def install_path_rules(self, path, src_ip, dst_ip, priority=100,
                       idle_timeout=0, hard_timeout=0, install_time=0.0):
    """Install a forwarding rule on every switch along ``path``.

    Returns the number of rules that were accepted.  The path is also
    remembered for the host pair it connects, so a later link failure knows
    which flows it disturbs.
    """
    installed = 0
    for index, node in enumerate(path or []):
        table = self.flow_tables.get(node)
        if table is None:
            continue
        next_hop = path[index + 1] if index + 1 < len(path) else None
        port = self.port_for(node, next_hop)
        rule = FlowRule({"src_ip": src_ip, "dst_ip": dst_ip},
                        [{"type": "output", "port": port}],
                        priority=priority, idle_timeout=idle_timeout,
                        hard_timeout=hard_timeout,
                        install_time=install_time)
        if table.install(rule):
            installed += 1
    self.rules_installed += installed
    src, dst = self.host_for_ip(src_ip), self.host_for_ip(dst_ip)
    if path and src is not None and dst is not None:
        self.paths[(src, dst)] = list(path)
    return installed

def remove_path_rules(self, path, src_ip, dst_ip):
    """Delete the rules a previous :meth:`install_path_rules` created."""
    removed = 0
    match = {"src_ip": src_ip, "dst_ip": dst_ip}
    for node in path or []:
        table = self.flow_tables.get(node)
        if table is not None and table.remove(match):
            removed += 1
    return removed

def total_rules_installed(self):
    """Rules currently present across every flow table."""
    return sum(table.size() for table in self.flow_tables.values())

def total_install_time(self):
    """Simulated time (ms) spent installing the rules that are in place."""
    return self.total_rules_installed() * self.rule_install_time_ms

def ip_of(self, host):
    return self.host_ips.get(host, host)

def host_for_ip(self, ip):
    """Reverse the host/IP mapping (used to resolve a packet's target)."""
    for host, host_ip in self.host_ips.items():
        if host_ip == ip:
            return host
    return None

def evict_expired(self, current_time, last_matched_times=None):
    """Run timeout eviction on every switch; returns the total evicted."""
    return sum(table.evict_expired(current_time, last_matched_times)
               for table in self.flow_tables.values())

def clear_rules(self):
    for table in self.flow_tables.values():
        table.clear()
    return self

# -- failure handling ---------------------------------------------------
def handle_link_failure(self, node1, node2, priority=100):
    """Drop a link and reinstall the paths that were using it.

    Returns the number of rules that were reinstalled on the new paths.
    """
    name1 = getattr(node1, "name", node1)
    name2 = getattr(node2, "name", node2)
    if not self.paths:
        self.compute_all_paths()
    affected = [(pair, path) for pair, path in self.paths.items()
                if self.path_uses_link(path, name1, name2)]
    self.remove_link(name1, name2)
    self.failed_links.append((name1, name2))
    reinstalled = 0
    for (src, dst), old_path in affected:
        src_ip, dst_ip = self.ip_of(src), self.ip_of(dst)
        self.remove_path_rules(old_path, src_ip, dst_ip)
        new_path = self.compute_path(src, dst)
        if not new_path:
            self.paths.pop((src, dst), None)
            continue
        self.paths[(src, dst)] = new_path
        reinstalled += self.install_path_rules(new_path, src_ip, dst_ip,
                                               priority=priority)
    return reinstalled

def affected_flows(self, node1, node2):
    """Host pairs whose current path crosses the given link."""
    name1 = getattr(node1, "name", node1)
    name2 = getattr(node2, "name", node2)
    return [pair for pair, path in self.paths.items()
            if self.path_uses_link(path, name1, name2)]

def __repr__(self):
    return "<%s %s switches=%d rules=%d>" % (
        type(self).__name__, self.name, len(self.flow_tables),
        self.total_rules_installed())

