import re, glob, subprocess, ast, os

src = {}
for path in glob.glob("netsim/**/*.py", recursive=True):
    src[path] = open(path).read()
all_src = "\n".join(src.values())

# collect defined names
defined = set()
for path, text in src.items():
    try:
        tree = ast.parse(text)
    except SyntaxError:
        continue
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)):
            defined.add(node.name)
        if isinstance(node, ast.Assign):
            for t in node.targets:
                if isinstance(t, ast.Name):
                    defined.add(t.id)
                if isinstance(t, ast.Attribute):
                    defined.add(t.attr)

missing = {}
for req in sorted(glob.glob("requirements/*.yaml")):
    text = open(req).read()
    names = set()
    # `Class`: / `method(self, ...)` / `attr` mentions in backticks
    for m in re.findall(r"`([A-Za-z_][A-Za-z0-9_]*)\s*\(", text):
        names.add(m)
    for m in re.findall(r"`([A-Za-z_][A-Za-z0-9_]*)`", text):
        names.add(m)
    miss = sorted(n for n in names if n not in defined)
    missing[os.path.basename(req)] = miss

for k, v in missing.items():
    print(k, "->", v)
