"""Class-scoped check: every `Class` -> `method(self,...)` block in each
requirement must resolve on the implemented class."""
import glob, importlib, inspect, re, os

modules = {}
for path in glob.glob("netsim/**/*.py", recursive=True):
    mod = path[:-3].replace("/", ".")
    try:
        modules[mod] = importlib.import_module(mod)
    except Exception as exc:
        print("IMPORT FAIL", mod, exc)

classes = {}
for mod in modules.values():
    for name, obj in vars(mod).items():
        if inspect.isclass(obj):
            classes.setdefault(name, obj)

problems = []
for req in sorted(glob.glob("requirements/*.yaml")):
    current = None
    for line in open(req):
        m = re.match(r"\s*-\s+`([A-Z][A-Za-z0-9_]*)`?(\(([A-Za-z0-9_, ]*)\))?`?\s*:", line)
        if m and m.group(1) in classes:
            current = classes[m.group(1)]
            continue
        m2 = re.match(r"\s*-\s+`([a-z_][A-Za-z0-9_]*)\(self", line)
        if m2 and current is not None:
            if not hasattr(current, m2.group(1)):
                problems.append((os.path.basename(req), current.__name__, m2.group(1)))
        m3 = re.match(r"\s*-\s+`([a-z_][A-Za-z0-9_]*)`\s*[,:]", line)
        if m3 and current is not None and not hasattr(current, m3.group(1)):
            # attribute described on the class; may be instance-only
            problems.append((os.path.basename(req), current.__name__, m3.group(1) + " (attr?)"))

print("class-scoped problems:", problems or "none")
